CREATE TABLE "CompanyAccount" ("userId" TEXT PRIMARY KEY REFERENCES "User"(id) ON DELETE CASCADE, "passwordHash" TEXT NOT NULL, "isAdmin" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "CompanySession" ("tokenHash" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "CompanyAccount"("userId") ON DELETE CASCADE, "expiresAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "CompanySession_expiresAt_idx" ON "CompanySession"("expiresAt");
CREATE TABLE "Company" (id TEXT PRIMARY KEY, name TEXT NOT NULL, "nameKey" TEXT NOT NULL UNIQUE, website TEXT NOT NULL, domain TEXT NOT NULL UNIQUE, published JSONB, revision INTEGER NOT NULL DEFAULT 0, "entityId" TEXT UNIQUE REFERENCES "Entity"(id) ON DELETE RESTRICT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CompanyMembership" (id TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, "userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT, status TEXT NOT NULL DEFAULT 'PENDING_REVIEW' CHECK(status IN ('PENDING_REVIEW','APPROVED','CHANGES_REQUESTED','REJECTED')), "businessEmail" TEXT NOT NULL, evidence TEXT NOT NULL, feedback TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("companyId","userId"));
CREATE TABLE "CompanySubmission" (id TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, "userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK(kind IN ('PROFILE','ROBOT','RESEARCH')), status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PENDING_REVIEW','APPROVED','CHANGES_REQUESTED','REJECTED')), proposed JSONB NOT NULL, baseline JSONB NOT NULL, "targetRobotId" TEXT REFERENCES "RobotModel"(id) ON DELETE RESTRICT, "publicId" TEXT, version INTEGER NOT NULL DEFAULT 1, feedback TEXT NOT NULL DEFAULT '', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "submittedAt" TIMESTAMP(3));
CREATE INDEX "CompanySubmission_companyId_status_idx" ON "CompanySubmission"("companyId",status);
CREATE TABLE "CompanyReview" (id TEXT PRIMARY KEY, "submissionId" TEXT REFERENCES "CompanySubmission"(id) ON DELETE RESTRICT, "membershipId" TEXT REFERENCES "CompanyMembership"(id) ON DELETE RESTRICT, "actorId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT, decision TEXT NOT NULL, feedback TEXT NOT NULL, snapshot JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CompanyRobot" ("companyId" TEXT NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, "robotId" TEXT NOT NULL UNIQUE REFERENCES "RobotModel"(id) ON DELETE RESTRICT, PRIMARY KEY("companyId","robotId"));
CREATE TABLE "CompanyRateLimit" (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "RobotModel_portal_normalized_name_key" ON "RobotModel" (lower(trim("canonicalName")));
